{
  "schema_version": 1,
  "action": "set_policy",
  "policy": {
    "model": "ae",
    "window": 3,
    "threshold_q": "default",
    "persistence": 3
  },
  "intent_understood_as": "balanced_operation",
  "reason": "Balanced operation requires <=5 false alarms/hour. AE at default threshold (q0.995) with persistence 1 yields 24.34/h, exceeding the budget. Raising persistence to 3 cuts false alarms to ~7.7/h (still above 5), but no other AE configuration meets the budget while maintaining detection. Persistence 3 is the best trade-off: it reduces false alarms significantly while preserving AE's novel-attack detection capability. Window 3 is the sane default per the capability card."
}
